def disclaimer_dialog():
    st.warning(
        f"This operation will block the app for {SLEEP_SECONDS} seconds. Do you want to continue?"
    )
    col1, col2 = st.columns(2)
    with col1:
        if st.button("OK"):
            st.session_state.accepted_disclaimer = True
            st.rerun()
    with col2:
        if st.button("Cancel"):
            st.session_state.accepted_disclaimer = False
            st.rerun()


# Initialize state
