    for i in range(SLEEP_SECONDS):
        time.sleep(1)
        pbar.progress((i + 1) / SLEEP_SECONDS, text=f"Sleeping... {i + 1}/{SLEEP_SECONDS}")
    st.success("Done!")

    # Reset state
    st.session_state.accepted_disclaimer = False

    st.button("OK")
